#!/usr/bin/env node
/* global __dirname */
/**
 * Builds src/lib/ota/whats-new.generated.ts from CHANGELOG.md, so the in-app "What's new" sheet
 * always says what the changelog says (docs/OTA.md). Run by `npm run whats-new`; the OTA guard
 * refuses to publish when the generated file is out of date.
 *
 *   node scripts/whats-new.js          write the file
 *   node scripts/whats-new.js --check  exit 1 if the file is out of date
 */
const { readFileSync, writeFileSync } = require("fs");
const { join } = require("path");

const KEEP = 6;

/** Parse CHANGELOG.md into [{ version, items: [{ title, body }] }], newest first. */
function parseChangelog(md) {
  const out = [];
  let cur = null;
  let bullet = null;
  let inBullets = false;
  const flush = () => {
    if (cur && bullet !== null) cur.items.push(bullet.trim().replace(/\s+/g, " "));
    bullet = null;
  };
  for (const line of md.split(/\r?\n/)) {
    const h = line.match(/^## (\d+\.\d+\.\d+)\b/);
    if (h) {
      flush();
      cur = { version: h[1], items: [] };
      out.push(cur);
      inBullets = true;
      continue;
    }
    if (!cur) continue;
    if (/^- /.test(line)) { flush(); if (inBullets) bullet = line.slice(2); continue; }
    if (bullet !== null && /^\s{2,}\S/.test(line)) { bullet += " " + line.trim(); continue; }
    if (line.trim() === "") { flush(); continue; }
    // Any other paragraph (for example "What to test") ends the list a reader sees.
    flush();
    inBullets = false;
  }
  flush();
  // A version can appear twice (two store builds with the same number): keep the first (newest).
  const seen = new Set();
  return out
    .filter((v) => (seen.has(v.version) ? false : (seen.add(v.version), true)))
    .map((v) => ({
      version: v.version,
      items: v.items
        .filter((t) => !/^Shipped over the air/i.test(t))
        .map((t) => {
          const m = t.match(/^([^:.]{2,40}):\s+(.+)$/);
          return m ? { title: m[1], body: m[2].charAt(0).toUpperCase() + m[2].slice(1) } : { title: "", body: t };
        }),
    }))
    .filter((v) => v.items.length > 0);
}

function render(entries) {
  const data = {};
  for (const e of entries.slice(0, KEEP)) data[e.version] = e.items;
  return [
    "// Generated by scripts/whats-new.js from CHANGELOG.md. Do not edit by hand: run npm run whats-new.",
    "export type WhatsNewItem = { title: string; body: string };",
    `export const WHATS_NEW: Record<string, WhatsNewItem[]> = ${JSON.stringify(data, null, 2)};`,
    "",
  ].join("\n");
}

const root = join(__dirname, "..");
const target = join(root, "src", "lib", "ota", "whats-new.generated.ts");

function expected() {
  return render(parseChangelog(readFileSync(join(root, "CHANGELOG.md"), "utf8")));
}

function upToDate() {
  try { return readFileSync(target, "utf8") === expected(); } catch { return false; }
}

if (require.main === module) {
  if (process.argv.includes("--check")) {
    if (!upToDate()) { console.error("src/lib/ota/whats-new.generated.ts is out of date: run npm run whats-new"); process.exit(1); }
    console.log("What's new is up to date with CHANGELOG.md");
  } else {
    writeFileSync(target, expected());
    console.log(`Wrote ${target}`);
  }
}

module.exports = { parseChangelog, render, upToDate, expected };
